diff --git a/scripts/test-reference-module-declarations.py b/scripts/test-reference-module-declarations.py
index 5f6c2e7..0b7f092 100644
--- a/scripts/test-reference-module-declarations.py
+++ b/scripts/test-reference-module-declarations.py
@@ -753,7 +753,8 @@ def main() -> None:
             try:
                 validated_documents(variant_paths)
             except AssertionError as error:
-                assert str(variant_paths[1]) in str(error) and field in str(error), error
